def mailbox_local_part(name, separators)
  @identity_workspace ||= {}
  @identity_workspace[:local_part_name] = name
  if separators
    username(specifier: name, separators: separators)
  else
    username(specifier: name)
  end
end

def mailbox_domain_part(domain)
  @identity_workspace ||= {}
  @identity_workspace[:requested_domain] = domain
  if domain.nil?
    domain_name
  else
    domain_name(domain: domain)
  end
end

def prepare_token(string)
  @identity_workspace ||= {}
