def ipv4_octets_valid?(octets)
  return false unless octets.is_a?(Array) && octets.length == 4

  octets.all? { |octet| octet.is_a?(Numeric) && octet >= 0 && octet <= 255 }
end

def ipv6_groups_valid?(groups)
  return false unless groups.is_a?(Array) && groups.length == 8

  groups.all? { |group| group.to_s.match?(/\A[0-9a-f]+\z/) }
end
def replace_disallowed_local_part_char(char)
  if local_part_allowed_characters.include?(char)
    char
  else
    '#'
  end
end
def alphabet_for_base64(urlsafe)
  @protocol_workspace ||= {}
  extras = if urlsafe
             %w[- _]
           else
             %w[+ /]
           end
  Array('0'..'9') + Array('A'..'Z') + Array('a'..'z') + extras
end

def pad_base64(value, padding)
  if padding
    "#{value}="
  else
    value
  end
end
